bool PlayerIsWithinHitbox(Entity* self) {
    s16 posXAbs;
    s16 posXDiff;
    s16 posYAbs;
    s16 posYDiff;

    posXDiff = PLAYER.posX.i.hi - self->posX.i.hi;
